import React from 'react';
import { t } from '../../i18n';
import { getGrammarProgress, saveGrammarProgress } from '../../lib/userService';
import './grammar_ES.css';

const GRAMMAR_LANGUAGE_ID = 'ES';

const assignSectionIds = (container) => {
	const subsections = container.querySelectorAll('.grammar-subsection');
	subsections.forEach((subsection, index) => {
		subsection.dataset.grammarId = String(index + 1);
	});
	return subsections;
};

const buildProgressPayload = (container) => {
	const subsections = assignSectionIds(container);
	return [...subsections]
		.map((subsection) => {
			const id = subsection.dataset.grammarId;
			if (!id) return null;
			return {
				id,
				result: subsection.classList.contains('is-completed') ? '1' : '0'
			};
		})
		.filter(Boolean);
};

const loadGrammarProgressIntoDom = async (container) => {
	if (!container || container.dataset.progressLoaded === '1') {
		return;
	}

	container.dataset.progressLoaded = '1';
	const subsections = assignSectionIds(container);
	const sectionIds = [...subsections].map((subsection) => subsection.dataset.grammarId).filter(Boolean);

	try {
		const progress = await getGrammarProgress(GRAMMAR_LANGUAGE_ID, sectionIds);
		const byId = new Map(progress.map((item) => [String(item.id), String(item.result) === '1']));
		subsections.forEach((subsection) => {
			const id = subsection.dataset.grammarId;
			subsection.classList.toggle('is-completed', byId.get(id) === true);
		});
	} catch (error) {
		console.error('Grammar progress load error:', error);
	}
};

